  ('u2-b5-e3', 'u2-b5', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"бір","english":"one"},{"kazakh":"екі","english":"two"},{"kazakh":"үш","english":"three"},{"kazakh":"тоғыз","english":"nine"},{"kazakh":"он","english":"ten"}]}'::jsonb, 'active', 'high'),
