  ('u2-b5-e5', 'u2-b5', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["","ір"],"options":["п","м","б"],"correctAns":"б","hintEn":"one — бір"}'::jsonb, 'active', 'high'),
  ('u2-b5-e6', 'u2-b5', 6, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"екі","options":["one","nine","two","three"],"correctAns":"two"}'::jsonb, 'active', 'high'),
  ('u2-b5-e7', 'u2-b5', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["тау",""],"options":["лер","лар"],"correctAns":"лар","hintEn":"mountains"}'::jsonb, 'active', 'high'),
  ('u2-b5-e8', 'u2-b5', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["терезе",""],"options":["лар","лер"],"correctAns":"лер","hintEn":"windows"}'::jsonb, 'active', 'high'),
  ('u2-b5-e9', 'u2-b5', 9, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"ұл","questionEn":"Is the last vowel soft or strong?","options":["Soft","Strong"],"correctAns":"Strong"}'::jsonb, 'active', 'high'),
  ('u2-b5-e10', 'u2-b5', 10, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"ш","questionEn":"Which group is this letter in?","options":["Voiceless","Voiced","Sonorant"],"correctAns":"Voiceless"}'::jsonb, 'active', 'high'),
  ('u2-b5-e11', 'u2-b5', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"әлем","options":["beautiful","art","hello","world"],"correctAns":"world"}'::jsonb, 'active', 'high'),
  ('u2-b5-e12', 'u2-b5', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"ұзын","options":["үзін","ұзын","озын"],"correctAns":"ұзын"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b1-e1', 'u3-b1', 1, 'TEACH', '{"type":"TEACH","title":"I, you, he, she…","table":{"headers":["Kazakh","English"],"rows":[["мен","I"],["сен","you (friendly)"],["сіз","you (polite)"],["ол","he / she / it"],["біз","we"],["сендер","you all (friendly)"],["сіздер","you all (polite)"],["олар","they"]]},"tip":"**Ол** means he, she *and* it — Kazakh has no grammatical gender."}'::jsonb, 'active', 'high'),
  ('u3-b1-e2', 'u3-b1', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"мен","english":"I"},{"kazakh":"сен","english":"you (friendly)"},{"kazakh":"ол","english":"he / she / it"},{"kazakh":"біз","english":"we"},{"kazakh":"олар","english":"they"}]}'::jsonb, 'active', 'high'),
  ('u3-b1-e3', 'u3-b1', 3, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"ол","options":["he / she / it","you","they","we"],"correctAns":"he / she / it"}'::jsonb, 'active', 'high'),
  ('u3-b1-e4', 'u3-b1', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"біз","options":["you","they","we","I"],"correctAns":"we"}'::jsonb, 'active', 'high'),
  ('u3-b1-e5', 'u3-b1', 5, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"сіз","questionEn":"Who would you call this?","options":["Your little sister","Your best friend''s dog","Your teacher"],"correctAns":"Your teacher"}'::jsonb, 'active', 'high'),
  ('u3-b1-e6', 'u3-b1', 6, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"сен","questionEn":"This “you” is…","options":["polite / formal","friendly / informal","he or she","plural only"],"correctAns":"friendly / informal"}'::jsonb, 'active', 'high'),
  ('u3-b1-e7', 'u3-b1', 7, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"сіз","english":"you (polite)"},{"kazakh":"сендер","english":"you all (friendly)"},{"kazakh":"сіздер","english":"you all (polite)"},{"kazakh":"мен","english":"I"},{"kazakh":"олар","english":"they"}]}'::jsonb, 'active', 'high'),
  ('u3-b1-e8', 'u3-b1', 8, 'LISTENING', '{"type":"LISTENING","audioKk":"сендер","options":["сендер","сіздер","сен"],"correctAns":"сендер"}'::jsonb, 'active', 'high'),
  ('u3-b1-e9', 'u3-b1', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"олар","options":["they","you all","we","he / she"],"correctAns":"they"}'::jsonb, 'active', 'high'),
  ('u3-b1-e10', 'u3-b1', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":[""," Сандромын."],"options":["Сен","Мен","Ол"],"correctAns":"Мен","hintEn":"I am Sandro."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b2-e1', 'u3-b2', 1, 'TEACH', '{"type":"TEACH","title":"There''s no word for “am”","body":["To say *I am a doctor*, Kazakh adds an ending to the word itself: **дәрігер** (doctor) → дәрігер**мін** (I am a doctor).","**Мен** (I) is optional: *Мен дәрігермін* = *Дәрігермін*."],"examples":[{"kk":"Мен дәрігер**мін**.","en":"I am a doctor."},{"kk":"Мен Сандро**мын**.","en":"I am Sandro."}]}'::jsonb, 'active', 'high'),
  ('u3-b2-e2', 'u3-b2', 2, 'TEACH', '{"type":"TEACH","title":"-мын or -мін?","body":["After a **vowel** or a **sonorant** (м н ң л р й у) use **-мын / -мін**.","Strong word → **-мын**. Soft word → **-мін**."],"examples":[{"kk":"Бала**мын**.","en":"I am a child."},{"kk":"Адам**мын**.","en":"I am a person."},{"kk":"Жақсы**мын**.","en":"I am good."},{"kk":"Инженер**мін**.","en":"I am an engineer."},{"kk":"Мұғалім**мін**.","en":"I am a teacher."},{"kk":"Әке**мін**.","en":"I am a father."}]}'::jsonb, 'active', 'high'),
  ('u3-b2-e3', 'u3-b2', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен дәрігер","."],"options":["пін","мін","мын"],"correctAns":"мін","hintEn":"I am a doctor."}'::jsonb, 'active', 'high'),
  ('u3-b2-e4', 'u3-b2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен адам","."],"options":["мын","мін","пын"],"correctAns":"мын","hintEn":"I am a person."}'::jsonb, 'active', 'high'),
  ('u3-b2-e5', 'u3-b2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен бала","."],"options":["мын","пын","мін"],"correctAns":"мын","hintEn":"I am a child."}'::jsonb, 'active', 'high'),
  ('u3-b2-e6', 'u3-b2', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен мұғалім","."],"options":["мын","пін","мін"],"correctAns":"мін","hintEn":"I am a teacher."}'::jsonb, 'active', 'high'),
  ('u3-b2-e7', 'u3-b2', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен хатшы","."],"options":["мын","мін","пын"],"correctAns":"мын","hintEn":"I am a secretary."}'::jsonb, 'active', 'high'),
  ('u3-b2-e8', 'u3-b2', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен әке","."],"options":["мін","пін","мын"],"correctAns":"мін","hintEn":"I am a father."}'::jsonb, 'active', 'high'),
  ('u3-b2-e9', 'u3-b2', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен инженермін.","options":["He is an engineer.","You are an engineer.","I am a teacher.","I am an engineer."],"correctAns":"I am an engineer."}'::jsonb, 'active', 'high'),
  ('u3-b2-e10', 'u3-b2', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен оқушымын.","options":["I am a teacher.","I am happy.","She is a student.","I am a student."],"correctAns":"I am a student."}'::jsonb, 'active', 'high'),
  ('u3-b2-e11', 'u3-b2', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am a teacher.","tiles":["Мен","мұғаліммін","мұғалім","сен"],"correctAns":["Мен","мұғаліммін"]}'::jsonb, 'active', 'high'),
  ('u3-b2-e12', 'u3-b2', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"дәрігермін","options":["дәрігерсің","дәрігер","дәрігермін"],"correctAns":"дәрігермін"}'::jsonb, 'active', 'high'),
  ('u3-b2-e13', 'u3-b2', 13, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"дәрігер","english":"doctor"},{"kazakh":"мұғалім","english":"teacher"},{"kazakh":"инженер","english":"engineer"},{"kazakh":"оқушы","english":"student"},{"kazakh":"хатшы","english":"secretary"}]}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b3-e1', 'u3-b3', 1, 'TEACH', '{"type":"TEACH","title":"Three families of “I am”","body":["The **last letter** picks м, б or п. The **last vowel** picks ы or і."],"table":{"headers":["Word ends in…","Strong","Soft"],"rows":[["vowel, м н ң л р й у","**-мын** · адам**мын**","**-мін** · дәрігер**мін**"],["ж з","**-бын** · қыз**бын**","**-бін** · тез**бін**"],["voiceless: к қ п с т ш…","**-пын** · қазақ**пын**","**-пін** · әріптес**пін**"]]}}'::jsonb, 'active', 'high'),
  ('u3-b3-e2', 'u3-b3', 2, 'TEACH', '{"type":"TEACH","title":"Examples","examples":[{"kk":"Аспаз**бын**.","en":"I am a chef."},{"kk":"Француз**бын**.","en":"I am French."},{"kk":"Ұшқыш**пын**.","en":"I am a pilot."},{"kk":"Қазақ**пын**.","en":"I am Kazakh."},{"kk":"Олжас**пын**.","en":"I am Olzhas."},{"kk":"Әріптес**пін**.","en":"I am a colleague."}],"tip":"Names work the same way: **Айжанмын**, **Мөлдірмін**, **Қанатпын**."}'::jsonb, 'active', 'high'),
  ('u3-b3-e3', 'u3-b3', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен аспаз","."],"options":["бін","бын","мын"],"correctAns":"бын","hintEn":"I am a chef."}'::jsonb, 'active', 'high'),
  ('u3-b3-e4', 'u3-b3', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен ұшқыш","."],"options":["пін","мын","пын"],"correctAns":"пын","hintEn":"I am a pilot."}'::jsonb, 'active', 'high'),
  ('u3-b3-e5', 'u3-b3', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен қазақ","."],"options":["пін","пын","мын"],"correctAns":"пын","hintEn":"I am Kazakh."}'::jsonb, 'active', 'high'),
  ('u3-b3-e6', 'u3-b3', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен француз","."],"options":["бін","бын","мын"],"correctAns":"бын","hintEn":"I am French."}'::jsonb, 'active', 'high'),
  ('u3-b3-e7', 'u3-b3', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен жұлдыз","."],"options":["мын","бын","бін"],"correctAns":"бын","hintEn":"I am a star."}'::jsonb, 'active', 'high'),
  ('u3-b3-e8', 'u3-b3', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен Мөлдір","."],"options":["пін","мын","мін"],"correctAns":"мін","hintEn":"I am Moldir."}'::jsonb, 'active', 'high'),
  ('u3-b3-e9', 'u3-b3', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен Қанат","."],"options":["мын","пын","пін"],"correctAns":"пын","hintEn":"I am Qanat."}'::jsonb, 'active', 'high'),
  ('u3-b3-e10', 'u3-b3', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен дайын","."],"options":["мін","пын","мын"],"correctAns":"мын","hintEn":"I am ready."}'::jsonb, 'active', 'high'),
  ('u3-b3-e11', 'u3-b3', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am Kazakh.","tiles":["Мен","қазақпын","қазақмын","қазақбын"],"correctAns":["Мен","қазақпын"]}'::jsonb, 'active', 'high'),
  ('u3-b3-e12', 'u3-b3', 12, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am a pilot.","tiles":["Мен","ұшқышпын","ұшқышмын","ұшқышбын"],"correctAns":["Мен","ұшқышпын"]}'::jsonb, 'active', 'high'),
  ('u3-b3-e13', 'u3-b3', 13, 'LISTENING', '{"type":"LISTENING","audioKk":"аспазбын","options":["аспазпын","аспазбын","аспазмын"],"correctAns":"аспазбын"}'::jsonb, 'active', 'high'),
  ('u3-b3-e14', 'u3-b3', 14, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен америкалықпын.","options":["I am American.","I am not American.","I am in America.","You are American."],"correctAns":"I am American."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b4-e1', 'u3-b4', 1, 'TEACH', '{"type":"TEACH","title":"Every person has an ending","body":["Here is **инженер** (engineer) with every pronoun:"],"table":{"headers":["Pronoun","Form","Meaning"],"rows":[["мен","инженер**мін**","I am an engineer"],["сен","инженер**сің**","you are (friendly)"],["сіз","инженер**сіз**","you are (polite)"],["ол","инженер","he / she is — no ending!"],["біз","инженер**міз**","we are"],["сендер","инженер**сіңдер**","you all are (friendly)"],["сіздер","инженер**сіздер**","you all are (polite)"],["олар","инженер**лер**","they are (plural noun)"]]}}'::jsonb, 'active', 'high'),
  ('u3-b4-e2', 'u3-b4', 2, 'TEACH', '{"type":"TEACH","title":"Strong & soft endings","table":{"headers":["Pronoun","Strong","Soft"],"rows":[["сен","-сың","-сің"],["сіз","-сыз","-сіз"],["біз","-мыз / -быз / -пыз","-міз / -біз / -піз"],["сендер","-сыңдар","-сіңдер"],["сіздер","-сыздар","-сіздер"]]},"tip":"**Біз** is special: after **м н ң** it takes **-быз / -біз**: адам**быз**, мұғалім**біз**.","examples":[{"kk":"Сен жақсы адам**сың**.","en":"You are a good person."},{"kk":"Ол жақсы адам.","en":"She is a good person."},{"kk":"Біз жақсы адам**быз**.","en":"We are good people."}]}'::jsonb, 'active', 'high'),
  ('u3-b4-e3', 'u3-b4', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сен ана","."],"options":["сің","сың","сыз"],"correctAns":"сың","hintEn":"You are a mother."}'::jsonb, 'active', 'high'),
  ('u3-b4-e4', 'u3-b4', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сіз ата","."],"options":["сың","сіз","сыз"],"correctAns":"сыз","hintEn":"You are a grandpa. (polite)"}'::jsonb, 'active', 'high'),
  ('u3-b4-e5', 'u3-b4', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Біз мұғалім","."],"options":["быз","біз","міз"],"correctAns":"біз","hintEn":"We are teachers."}'::jsonb, 'active', 'high'),
  ('u3-b4-e6', 'u3-b4', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Біз ұшқыш","."],"options":["піз","пыз","мыз"],"correctAns":"пыз","hintEn":"We are pilots."}'::jsonb, 'active', 'high'),
  ('u3-b4-e7', 'u3-b4', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Біз дәрігер","."],"options":["піз","міз","мыз"],"correctAns":"міз","hintEn":"We are doctors."}'::jsonb, 'active', 'high'),
  ('u3-b4-e8', 'u3-b4', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сендер жақсы","."],"options":["сіңдер","сыңдар","сыздар"],"correctAns":"сыңдар","hintEn":"You (all) are good."}'::jsonb, 'active', 'high'),
  ('u3-b4-e9', 'u3-b4', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сіздер жақсы адам","."],"options":["сыңдар","сіздер","сыздар"],"correctAns":"сыздар","hintEn":"You (all) are good people."}'::jsonb, 'active', 'high'),
  ('u3-b4-e10', 'u3-b4', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Біз бала","."],"options":["міз","мыз","пыз"],"correctAns":"мыз","hintEn":"We are children."}'::jsonb, 'active', 'high'),
  ('u3-b4-e11', 'u3-b4', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Біз жақсы адамбыз.","options":["They are good people.","You are good people.","We are good people.","I am a good person."],"correctAns":"We are good people."}'::jsonb, 'active', 'high'),
  ('u3-b4-e12', 'u3-b4', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Ол мейірімді қыз.","options":["You are a kind girl.","She is a good girl.","She is a kind girl.","This is my girl."],"correctAns":"She is a kind girl."}'::jsonb, 'active', 'high'),
  ('u3-b4-e13', 'u3-b4', 13, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"You are a good doctor. (polite)","tiles":["Сіз","жақсы","дәрігерсіз","дәрігермін","сен"],"correctAns":["Сіз","жақсы","дәрігерсіз"]}'::jsonb, 'active', 'high'),
  ('u3-b4-e14', 'u3-b4', 14, 'LISTENING', '{"type":"LISTENING","audioKk":"мейірімдісіңдер","options":["мейірімдісіңдер","мейірімдіміз","мейірімдісіздер"],"correctAns":"мейірімдісіңдер"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b5-e1', 'u3-b5', 1, 'TEACH', '{"type":"TEACH","title":"Not = емес","body":["To say *not*, put **емес** after the word, and move the ending onto **емес**.","Емес ends in **с** (voiceless, soft), so it always takes **-пін, -сің, -сіз, -піз, -сіңдер, -сіздер**."],"examples":[{"kk":"Мен мұғаліммін. → Мен мұғалім емес**пін**.","en":"I am a teacher. → I am not a teacher."},{"kk":"Сен инженер емес**сің**.","en":"You are not an engineer."},{"kk":"Ол дәрігер емес.","en":"She is not a doctor."},{"kk":"Біз мұғалім емес**піз**.","en":"We are not teachers."},{"kk":"Бұл телефон емес.","en":"This is not a phone."}]}'::jsonb, 'active', 'high'),
  ('u3-b5-e2', 'u3-b5', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен дәрігер емес","."],"options":["пын","пін","мін"],"correctAns":"пін","hintEn":"I am not a doctor."}'::jsonb, 'active', 'high'),
  ('u3-b5-e3', 'u3-b5', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сіз әже емес","."],"options":["сің","сіз","сыз"],"correctAns":"сіз","hintEn":"You are not a grandma. (polite)"}'::jsonb, 'active', 'high'),
  ('u3-b5-e4', 'u3-b5', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сен ұл емес","."],"options":["сың","пін","сің"],"correctAns":"сің","hintEn":"You are not a boy."}'::jsonb, 'active', 'high'),
  ('u3-b5-e5', 'u3-b5', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Біз жақсы адам емес","."],"options":["быз","піз","пыз"],"correctAns":"піз","hintEn":"We are not good people."}'::jsonb, 'active', 'high'),
  ('u3-b5-e6', 'u3-b5', 6, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am not French.","tiles":["Мен","француз","емеспін","французбын","емес"],"correctAns":["Мен","француз","емеспін"]}'::jsonb, 'active', 'high'),
  ('u3-b5-e7', 'u3-b5', 7, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Ол мейірімді қыз емес.","options":["She is not a kind girl.","She is a kind girl.","I am not a kind girl.","This is not a girl."],"correctAns":"She is not a kind girl."}'::jsonb, 'active', 'high'),
  ('u3-b5-e8', 'u3-b5', 8, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Бұл Педро емес.","options":["This is not Pedro.","I am not Pedro.","Pedro is not here.","This is Pedro."],"correctAns":"This is not Pedro."}'::jsonb, 'active', 'high'),
  ('u3-b5-e9', 'u3-b5', 9, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"Мен қазақ емеспін.","questionEn":"What does it mean?","options":["I am Kazakh.","I am not Kazakh.","You are not Kazakh.","We are Kazakh."],"correctAns":"I am not Kazakh."}'::jsonb, 'active', 'high'),
  ('u3-b5-e10', 'u3-b5', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am not a teacher, I am an engineer.","tiles":["Мен","мұғалім","емеспін","инженермін","мұғаліммін","инженер"],"correctAns":["Мен","мұғалім","емеспін","инженермін"]}'::jsonb, 'active', 'high'),
  ('u3-b5-e11', 'u3-b5', 11, 'LISTENING', '{"type":"LISTENING","audioKk":"емеспін","options":["емеспін","емеспіз","емессің"],"correctAns":"емеспін"}'::jsonb, 'active', 'high'),
  ('u3-b5-e12', 'u3-b5', 12, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"мейірімді","english":"kind"},{"kazakh":"бұл","english":"this"},{"kazakh":"емес","english":"not"},{"kazakh":"ата","english":"grandpa"},{"kazakh":"әже","english":"grandma"}]}'::jsonb, 'active', 'high'),
  ('u3-b5-e13', 'u3-b5', 13, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"You are not a grandma. (friendly)","tiles":["Сен","әже","емессің","әжесің","сіз"],"correctAns":["Сен","әже","емессің"]}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u4-b1-e1', 'u4-b1', 1, 'TEACH', '{"type":"TEACH","title":"Many = one ending","body":["Kazakh makes plurals with one ending in six shapes. Which one depends on the **last letter** and on **harmony**.","After a **vowel** or **р, й, у** → **-лар** (strong) / **-лер** (soft)."],"examples":[{"kk":"бала → бала**лар**","en":"child → children"},{"kk":"қала → қала**лар**","en":"city → cities"},{"kk":"үй → үй**лер**","en":"house → houses"},{"kk":"бөлме → бөлме**лер**","en":"room → rooms"},{"kk":"тау → тау**лар**","en":"mountain → mountains"},{"kk":"компьютер → компьютер**лер**","en":"computer → computers"}],"tip":"The plural ending is stressed: балал**а**р."}'::jsonb, 'active', 'high'),
  ('u4-b1-e2', 'u4-b1', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["алма",""],"options":["дар","лар","лер"],"correctAns":"лар","hintEn":"apples"}'::jsonb, 'active', 'high'),
  ('u4-b1-e3', 'u4-b1', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["дала",""],"options":["дар","лер","лар"],"correctAns":"лар","hintEn":"steppes"}'::jsonb, 'active', 'high'),
  ('u4-b1-e4', 'u4-b1', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["әке",""],"options":["дер","лер","лар"],"correctAns":"лер","hintEn":"fathers"}'::jsonb, 'active', 'high'),
  ('u4-b1-e5', 'u4-b1', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["қой",""],"options":["дар","лар","лер"],"correctAns":"лар","hintEn":"sheep (plural)"}'::jsonb, 'active', 'high'),
  ('u4-b1-e6', 'u4-b1', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["терезе",""],"options":["лар","лер","дер"],"correctAns":"лер","hintEn":"windows"}'::jsonb, 'active', 'high'),
  ('u4-b1-e7', 'u4-b1', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["пәтер",""],"options":["дер","лер","лар"],"correctAns":"лер","hintEn":"apartments"}'::jsonb, 'active', 'high'),
  ('u4-b1-e8', 'u4-b1', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["көрші",""],"options":["лар","лер","дер"],"correctAns":"лер","hintEn":"neighbours"}'::jsonb, 'active', 'high'),
  ('u4-b1-e9', 'u4-b1', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"қалалар","options":["children","a city","cities","steppes"],"correctAns":"cities"}'::jsonb, 'active', 'high'),
  ('u4-b1-e10', 'u4-b1', 10, 'LISTENING', '{"type":"LISTENING","audioKk":"үйлер","options":["үй","үйлер","үйлар"],"correctAns":"үйлер"}'::jsonb, 'active', 'high'),
