insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u4-b4-e1', 'u4-b4', 1, 'TEACH', '{"type":"TEACH","title":"No plural after numbers","body":["With a **number** or **көп** (many), the noun stays **singular**."],"examples":[{"kk":"алма**лар**","en":"apples"},{"kk":"екі алма","en":"two apples"},{"kk":"көп алма","en":"many apples"},{"kk":"үш қыз","en":"three girls"},{"kk":"бір ит","en":"one dog"}],"tip":"**Екі қызбыз** = *We are two girls*, but **Қыздармыз** = *We are girls*."}'::jsonb, 'active', 'high'),
  ('u4-b4-e2', 'u4-b4', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Екі ","."],"options":["алмалар","алма"],"correctAns":"алма","hintEn":"two apples"}'::jsonb, 'active', 'high'),
  ('u4-b4-e3', 'u4-b4', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Көп ","."],"options":["адамдар","адам"],"correctAns":"адам","hintEn":"many people"}'::jsonb, 'active', 'high'),
  ('u4-b4-e4', 'u4-b4', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"екі ит","options":["dogs","many dogs","a dog","two dogs"],"correctAns":"two dogs"}'::jsonb, 'active', 'high'),
  ('u4-b4-e5', 'u4-b4', 5, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"үш мысық","options":["one cat","three cats","three dogs","cats"],"correctAns":"three cats"}'::jsonb, 'active', 'high'),
  ('u4-b4-e6', 'u4-b4', 6, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"many books","tiles":["көп","кітап","кітаптар","бір"],"correctAns":["көп","кітап"]}'::jsonb, 'active', 'high'),
  ('u4-b4-e7', 'u4-b4', 7, 'TEACH', '{"type":"TEACH","title":"They are… → plural","body":["With **олар** (they), a noun takes the plural: Олар инженер**лер**. — *They are engineers.*","Adjectives and **емес** don''t take plural endings: **Олар жақсы.** — *They are good.*"],"examples":[{"kk":"Олар дәрігер**лер**.","en":"They are doctors."},{"kk":"Олар жақсы дәрігер**лер**.","en":"They are good doctors."},{"kk":"Қыздар**мыз**.","en":"We are girls."}]}'::jsonb, 'active', 'high'),
  ('u4-b4-e8', 'u4-b4', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Олар дәрігер","."],"options":["лар","дер","лер"],"correctAns":"лер","hintEn":"They are doctors."}'::jsonb, 'active', 'high'),
  ('u4-b4-e9', 'u4-b4', 9, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"They are engineers.","tiles":["Олар","инженерлер","инженер","біз"],"correctAns":["Олар","инженерлер"]}'::jsonb, 'active', 'high'),
  ('u4-b4-e10', 'u4-b4', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Олар жақсы дәрігерлер.","options":["We are good doctors.","They are good doctors.","She is a good doctor.","They are not doctors."],"correctAns":"They are good doctors."}'::jsonb, 'active', 'high'),
  ('u4-b4-e11', 'u4-b4', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қыздармыз.","options":["We are girls.","I am a girl.","They are girls.","We are two girls."],"correctAns":"We are girls."}'::jsonb, 'active', 'high'),
  ('u4-b4-e12', 'u4-b4', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Екі қызбыз.","options":["We are girls.","Two girls are here.","We are two girls.","I have two girls."],"correctAns":"We are two girls."}'::jsonb, 'active', 'high'),
