  ('u5-b2-e5', 'u5-b2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Менің ","."],"options":["ініім","інің","інім"],"correctAns":"інім","hintEn":"my younger brother"}'::jsonb, 'active', 'high'),
