insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u5-b4-e1', 'u5-b4', 1, 'TEACH', '{"type":"TEACH","title":"“Have” = my … exists","body":["Kazakh has no verb *to have*. Instead say *my cat exists*: **Мысығым бар.** = *I have a cat.*","For *don''t have*, use **жоқ** (*there isn''t*): **Мысығым жоқ.** = *I don''t have a cat.*"],"examples":[{"kk":"Қызым **бар**.","en":"I have a daughter."},{"kk":"Балаларым **бар**.","en":"I have kids."},{"kk":"Телефоным **жоқ**.","en":"I don''t have a phone."},{"kk":"Жақсы жұмысым **бар**.","en":"I have a good job."},{"kk":"Екі орындығымыз **бар**.","en":"We have two chairs."}]}'::jsonb, 'active', 'high'),
  ('u5-b4-e2', 'u5-b4', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қызым бар.","options":["I have a daughter.","My daughter is here.","I don''t have a daughter.","I am a daughter."],"correctAns":"I have a daughter."}'::jsonb, 'active', 'high'),
  ('u5-b4-e3', 'u5-b4', 3, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мысығым жоқ.","options":["I don''t have a cat.","My cat is not big.","I have a cat.","This is not my cat."],"correctAns":"I don''t have a cat."}'::jsonb, 'active', 'high'),
  ('u5-b4-e4', 'u5-b4', 4, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I have an apple.","tiles":["Алмам","бар","жоқ","алма"],"correctAns":["Алмам","бар"]}'::jsonb, 'active', 'high'),
  ('u5-b4-e5', 'u5-b4', 5, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I don''t have a phone.","tiles":["Телефоным","жоқ","бар","емес"],"correctAns":["Телефоным","жоқ"]}'::jsonb, 'active', 'high'),
  ('u5-b4-e6', 'u5-b4', 6, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"We have a good big house.","tiles":["Жақсы","үлкен","үйіміз","бар","жоқ","үйім"],"correctAns":["Жақсы","үлкен","үйіміз","бар"]}'::jsonb, 'active', 'high'),
  ('u5-b4-e7', 'u5-b4', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мысығым ","."],"options":["жоқ","бар","емес"],"correctAns":"жоқ","hintEn":"I don''t have a cat."}'::jsonb, 'active', 'high'),
  ('u5-b4-e8', 'u5-b4', 8, 'TEACH', '{"type":"TEACH","title":"Questions & емес vs жоқ","body":["Add **ма** to ask: **Сұрағың бар ма?** = *Do you have a question?*","**емес** = *is not* (describes something): **Үйіміз үлкен емес.** = *Our house is not big.*","**жоқ** = *there is no / don''t have*: **Мысығымыз жоқ.** = *We don''t have a cat.*"],"examples":[{"kk":"Сұрағыңыз бар ма?","en":"Do you have a question? (polite)"},{"kk":"Иә, бар.","en":"Yes, I do."},{"kk":"Жоқ, сұрағым жоқ.","en":"No, I don''t have a question."}]}'::jsonb, 'active', 'high'),
  ('u5-b4-e9', 'u5-b4', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Үйіміз үлкен ","."],"options":["жоқ","емес","бар"],"correctAns":"емес","hintEn":"Our house is not big."}'::jsonb, 'active', 'high'),
  ('u5-b4-e10', 'u5-b4', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сұрағың бар ","?"],"options":["ме","ма","ба"],"correctAns":"ма","hintEn":"Do you have a question?"}'::jsonb, 'active', 'high'),
  ('u5-b4-e11', 'u5-b4', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сұрағыңыз бар ма?","options":["I have a question.","Where is your question?","Is this your question?","Do you have a question?"],"correctAns":"Do you have a question?"}'::jsonb, 'active', 'high'),
  ('u5-b4-e12', 'u5-b4', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"балаларым бар","options":["балаларым бар","балам бар","балаларым жоқ"],"correctAns":"балаларым бар"}'::jsonb, 'active', 'high'),
  ('u5-b4-e13', 'u5-b4', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Үлкен итіңіз бар.","options":["Your dog is big.","I have a big dog.","You don''t have a dog.","You have a big dog."],"correctAns":"You have a big dog."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u5-b5-e1', 'u5-b5', 1, 'TEACH', '{"type":"TEACH","title":"Review: two kinds of endings","body":["Don''t mix them up: *I am* endings go on what you **are**; possessive endings go on what you **have**."],"table":{"headers":["my (possessive)","I am (personal)"],"rows":[["қыз**ым** — my daughter","қыз**бын** — I am a girl"],["әріптес**ім** — my colleague","әріптес**пін** — I am a colleague"],["дәрігер**ім** — my doctor","дәрігер**мін** — I am a doctor"]]}}'::jsonb, 'active', 'high'),
  ('u5-b5-e2', 'u5-b5', 2, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My daughter is a student.","tiles":["Қызым","оқушы","оқушымын","қызың"],"correctAns":["Қызым","оқушы"]}'::jsonb, 'active', 'high'),
  ('u5-b5-e3', 'u5-b5', 3, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My cat is big.","tiles":["Мысығым","үлкен","мысық","бар"],"correctAns":["Мысығым","үлкен"]}'::jsonb, 'active', 'high'),
  ('u5-b5-e4', 'u5-b5', 4, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My family is not big.","tiles":["Отбасым","үлкен","емес","жоқ","отбасы"],"correctAns":["Отбасым","үлкен","емес"]}'::jsonb, 'active', 'high'),
  ('u5-b5-e5', 'u5-b5', 5, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"We don''t have a cat.","tiles":["Мысығымыз","жоқ","емес","мысығым"],"correctAns":["Мысығымыз","жоқ"]}'::jsonb, 'active', 'high'),
  ('u5-b5-e6', 'u5-b5', 6, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Жұмысым жақсы.","options":["My work is good.","I have good work.","Your work is good.","I work well."],"correctAns":"My work is good."}'::jsonb, 'active', 'high'),
  ('u5-b5-e7', 'u5-b5', 7, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I have a big table.","tiles":["Үлкен","үстелім","бар","жоқ","үстел"],"correctAns":["Үлкен","үстелім","бар"]}'::jsonb, 'active', 'high'),
  ('u5-b5-e8', 'u5-b5', 8, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қызым инженер емес.","options":["My daughter is not an engineer.","I don''t have a daughter.","I am not an engineer.","My daughter is an engineer."],"correctAns":"My daughter is not an engineer."}'::jsonb, 'active', 'high'),
  ('u5-b5-e9', 'u5-b5', 9, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Your house is not big.","tiles":["Сенің","үйің","үлкен","емес","үйім","жоқ"],"correctAns":["Сенің","үйің","үлкен","емес"]}'::jsonb, 'active', 'high'),
  ('u5-b5-e10', 'u5-b5', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Атым Энди емес.","options":["His name is not Andy.","My name is not Andy.","Andy is not here.","My name is Andy."],"correctAns":"My name is not Andy."}'::jsonb, 'active', 'high'),
  ('u5-b5-e11', 'u5-b5', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Бір қарындасым бар.","options":["I have two younger sisters.","I have one younger sister.","My sister is young.","I am one younger sister."],"correctAns":"I have one younger sister."}'::jsonb, 'active', 'high'),
  ('u5-b5-e12', 'u5-b5', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Жақсы ата-анамыз бар.","options":["I have good parents.","We have good parents.","We are good parents.","Our grandparents are good."],"correctAns":"We have good parents."}'::jsonb, 'active', 'high'),
  ('u5-b5-e13', 'u5-b5', 13, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":[""," әдемі."],"options":["қалаң","қалаым","қалам"],"correctAns":"қалам","hintEn":"My city is beautiful."}'::jsonb, 'active', 'high'),
  ('u5-b5-e14', 'u5-b5', 14, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"үлкен","english":"big"},{"kazakh":"әдемі","english":"beautiful"},{"kazakh":"жақсы","english":"good"},{"kazakh":"үй","english":"house"},{"kazakh":"жұмыс","english":"work"}]}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u6-b1-e1', 'u6-b1', 1, 'TEACH', '{"type":"TEACH","title":"Counting to ten","table":{"headers":["","Kazakh","","Kazakh"],"rows":[["1","бір","6","алты"],["2","екі","7","жеті"],["3","үш","8","сегіз"],["4","төрт","9","тоғыз"],["5","бес","10","он"]]},"tip":"**он** = 10, but **оң** = right. Watch the ң!"}'::jsonb, 'active', 'high'),
  ('u6-b1-e2', 'u6-b1', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"бір","english":"1"},{"kazakh":"екі","english":"2"},{"kazakh":"үш","english":"3"},{"kazakh":"төрт","english":"4"},{"kazakh":"бес","english":"5"}]}'::jsonb, 'active', 'high'),
  ('u6-b1-e3', 'u6-b1', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"алты","english":"6"},{"kazakh":"жеті","english":"7"},{"kazakh":"сегіз","english":"8"},{"kazakh":"тоғыз","english":"9"},{"kazakh":"он","english":"10"}]}'::jsonb, 'active', 'high'),
  ('u6-b1-e4', 'u6-b1', 4, 'LISTENING', '{"type":"LISTENING","audioKk":"жеті","options":["сегіз","жеті","екі"],"correctAns":"жеті"}'::jsonb, 'active', 'high'),
