  ('u6-b1-e6', 'u6-b1', 6, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"бес","questionEn":"Which number is this?","options":["8","3","6","5"],"correctAns":"5"}'::jsonb, 'active', 'high'),
  ('u6-b1-e7', 'u6-b1', 7, 'TEACH', '{"type":"TEACH","title":"11 to 19","body":["Just stack them, like *ten-one*: **он бір** = 11, **он екі** = 12, **он бес** = 15."]}'::jsonb, 'active', 'high'),
  ('u6-b1-e8', 'u6-b1', 8, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"он екі","options":["20","11","12","2"],"correctAns":"12"}'::jsonb, 'active', 'high'),
  ('u6-b1-e9', 'u6-b1', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["он ",""],"options":["екі","бес","бір"],"correctAns":"бір","hintEn":"11"}'::jsonb, 'active', 'high'),
  ('u6-b1-e10', 'u6-b1', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"13","tiles":["он","үш","бір","жеті"],"correctAns":["он","үш"]}'::jsonb, 'active', 'high'),
  ('u6-b1-e11', 'u6-b1', 11, 'LISTENING', '{"type":"LISTENING","audioKk":"төрт","options":["төрт","бес","тоғыз"],"correctAns":"төрт"}'::jsonb, 'active', 'high'),
  ('u6-b1-e12', 'u6-b1', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"алты","options":["6","1","7","60"],"correctAns":"6"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u6-b2-e1', 'u6-b2', 1, 'TEACH', '{"type":"TEACH","title":"Tens","table":{"headers":["","Kazakh","","Kazakh"],"rows":[["20","жиырма","60","алпыс"],["30","отыз","70","жетпіс"],["40","қырық","80","сексен"],["50","елу","90","тоқсан"],["","","100","жүз"]]},"body":["Build any number like in English: **отыз төрт** = 34, **жиырма бір** = 21."]}'::jsonb, 'active', 'high'),
  ('u6-b2-e2', 'u6-b2', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"жиырма","english":"20"},{"kazakh":"отыз","english":"30"},{"kazakh":"қырық","english":"40"},{"kazakh":"елу","english":"50"},{"kazakh":"жүз","english":"100"}]}'::jsonb, 'active', 'high'),
  ('u6-b2-e3', 'u6-b2', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"алпыс","english":"60"},{"kazakh":"жетпіс","english":"70"},{"kazakh":"сексен","english":"80"},{"kazakh":"тоқсан","english":"90"},{"kazakh":"он","english":"10"}]}'::jsonb, 'active', 'high'),
  ('u6-b2-e4', 'u6-b2', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"отыз төрт","options":["43","30","34","24"],"correctAns":"34"}'::jsonb, 'active', 'high'),
  ('u6-b2-e5', 'u6-b2', 5, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"21","tiles":["жиырма","бір","он","екі"],"correctAns":["жиырма","бір"]}'::jsonb, 'active', 'high'),
  ('u6-b2-e6', 'u6-b2', 6, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"елу бес","options":["45","50","15","55"],"correctAns":"55"}'::jsonb, 'active', 'high'),
  ('u6-b2-e7', 'u6-b2', 7, 'TEACH', '{"type":"TEACH","title":"How old? — жаста","body":["For age, use the number + **жаста** (*at the age of*).","Add *I am*: Мен отыз жаста**мын**. = *I am 30.*"],"examples":[{"kk":"Қызым он жаста.","en":"My daughter is 10."},{"kk":"Досым отыз төрт жаста.","en":"My friend is 34."},{"kk":"Мен отыз жаста**мын**.","en":"I am 30."}]}'::jsonb, 'active', 'high'),
  ('u6-b2-e8', 'u6-b2', 8, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қызым он жаста.","options":["My son is 10 years old.","I have ten daughters.","My daughter is 20 years old.","My daughter is 10 years old."],"correctAns":"My daughter is 10 years old."}'::jsonb, 'active', 'high'),
  ('u6-b2-e9', 'u6-b2', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Досым отыз төрт жаста.","options":["My friend is 43 years old.","I have 34 friends.","My friend is 34 years old.","I am 34 years old."],"correctAns":"My friend is 34 years old."}'::jsonb, 'active', 'high'),
  ('u6-b2-e10', 'u6-b2', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am 30 years old.","tiles":["Мен","отыз","жастамын","жаста","он"],"correctAns":["Мен","отыз","жастамын"]}'::jsonb, 'active', 'high'),
  ('u6-b2-e11', 'u6-b2', 11, 'LISTENING', '{"type":"LISTENING","audioKk":"қырық","options":["қырқы","қырық","қыз"],"correctAns":"қырық"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u6-b3-e1', 'u6-b3', 1, 'TEACH', '{"type":"TEACH","title":"Where? — one ending","body":["**-да / -де / -та / -те** = *in / on / at*.","After a **voiceless** consonant (к қ п с т ш…) → **-та / -те**. After everything else → **-да / -де**."],"examples":[{"kk":"үй**де**","en":"at home"},{"kk":"жұмыс**та**","en":"at work"},{"kk":"қала**да**","en":"in the city"},{"kk":"дала**да**","en":"outside"},{"kk":"Сингапур**да**","en":"in Singapore"},{"kk":"Бангкок**та**","en":"in Bangkok"},{"kk":"Шымкент**те**","en":"in Shymkent"},{"kk":"Берлин**де**","en":"in Berlin"}]}'::jsonb, 'active', 'high'),
  ('u6-b3-e2', 'u6-b3', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["қала",""],"options":["та","да","де"],"correctAns":"да","hintEn":"in the city"}'::jsonb, 'active', 'high'),
  ('u6-b3-e3', 'u6-b3', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["үй",""],"options":["те","да","де"],"correctAns":"де","hintEn":"at home"}'::jsonb, 'active', 'high'),
  ('u6-b3-e4', 'u6-b3', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["жұмыс",""],"options":["та","те","да"],"correctAns":"та","hintEn":"at work"}'::jsonb, 'active', 'high'),
  ('u6-b3-e5', 'u6-b3', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Алматы",""],"options":["та","да","де"],"correctAns":"да","hintEn":"in Almaty"}'::jsonb, 'active', 'high'),
  ('u6-b3-e6', 'u6-b3', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Шымкент",""],"options":["те","де","та"],"correctAns":"те","hintEn":"in Shymkent"}'::jsonb, 'active', 'high'),
  ('u6-b3-e7', 'u6-b3', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["мектеп",""],"options":["та","те","де"],"correctAns":"те","hintEn":"at school"}'::jsonb, 'active', 'high'),
  ('u6-b3-e8', 'u6-b3', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["кафе",""],"options":["да","де","те"],"correctAns":"де","hintEn":"in a café"}'::jsonb, 'active', 'high'),
  ('u6-b3-e9', 'u6-b3', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["ресторан",""],"options":["де","да","та"],"correctAns":"да","hintEn":"in a restaurant"}'::jsonb, 'active', 'high'),
  ('u6-b3-e10', 'u6-b3', 10, 'TEACH', '{"type":"TEACH","title":"I''m at… / I live in…","body":["Add *I am* to a place: Мен үйде**мін**. = *I''m at home.*","**Тұрамын** = *I live*. **Сингапурда тұрамын.** = *I live in Singapore.* (more on verbs in Unit 7)"],"examples":[{"kk":"Мен дүкенде**мін**.","en":"I''m at the shop."},{"kk":"Сингапурда тұрамын.","en":"I live in Singapore."},{"kk":"Досым Италияда тұрады.","en":"My friend lives in Italy."},{"kk":"Кофе үстелде емес.","en":"The coffee is not on the table."}]}'::jsonb, 'active', 'high'),
  ('u6-b3-e11', 'u6-b3', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен үйдемін.","options":["I am at home.","I am home-made.","I live at home.","My house is here."],"correctAns":"I am at home."}'::jsonb, 'active', 'high'),
  ('u6-b3-e12', 'u6-b3', 12, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I live in Singapore.","tiles":["Сингапурда","тұрамын","Сингапур","тұрады"],"correctAns":["Сингапурда","тұрамын"]}'::jsonb, 'active', 'high'),
  ('u6-b3-e13', 'u6-b3', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Досым Италияда тұрады.","options":["My friend goes to Italy.","My friend is from Italy.","My friend lives in Italy.","I live in Italy."],"correctAns":"My friend lives in Italy."}'::jsonb, 'active', 'high'),
  ('u6-b3-e14', 'u6-b3', 14, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Кофе үстелде емес.","options":["There is no coffee.","The coffee is not on the table.","The table is not here.","The coffee is on the table."],"correctAns":"The coffee is not on the table."}'::jsonb, 'active', 'high'),
  ('u6-b3-e15', 'u6-b3', 15, 'LISTENING', '{"type":"LISTENING","audioKk":"далада","options":["далада","қалада","дала"],"correctAns":"далада"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u6-b4-e1', 'u6-b4', 1, 'TEACH', '{"type":"TEACH","title":"At … o''clock","body":["**Сағат** = hour / clock / watch. *At 5 o''clock* = **сағат бесте**: the number takes **-да/-де/-та/-те**."],"table":{"headers":["Time","Kazakh","Time","Kazakh"],"rows":[["at 1","сағат бір**де**","at 7","сағат жеті**де**"],["at 2","сағат екі**де**","at 8","сағат сегіз**де**"],["at 3","сағат үш**те**","at 9","сағат тоғыз**да**"],["at 4","сағат төрт**те**","at 10","сағат он**да**"],["at 5","сағат бес**те**","at 11","сағат он бір**де**"],["at 6","сағат алты**да**","at 12","сағат он екі**де**"]]}}'::jsonb, 'active', 'high'),
  ('u6-b4-e2', 'u6-b4', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат бес",""],"options":["те","де","та"],"correctAns":"те","hintEn":"at 5 o''clock"}'::jsonb, 'active', 'high'),
  ('u6-b4-e3', 'u6-b4', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат алты",""],"options":["да","де","та"],"correctAns":"да","hintEn":"at 6 o''clock"}'::jsonb, 'active', 'high'),
  ('u6-b4-e4', 'u6-b4', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат үш",""],"options":["де","те","та"],"correctAns":"те","hintEn":"at 3 o''clock"}'::jsonb, 'active', 'high'),
  ('u6-b4-e5', 'u6-b4', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат сегіз",""],"options":["де","те","да"],"correctAns":"де","hintEn":"at 8 o''clock"}'::jsonb, 'active', 'high'),
  ('u6-b4-e6', 'u6-b4', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат он",""],"options":["де","та","да"],"correctAns":"да","hintEn":"at 10 o''clock"}'::jsonb, 'active', 'high'),
  ('u6-b4-e7', 'u6-b4', 7, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"сағат бесте","options":["five watches","at 5 o''clock","it''s 5 o''clock","5 hours"],"correctAns":"at 5 o''clock"}'::jsonb, 'active', 'high'),
  ('u6-b4-e8', 'u6-b4', 8, 'TEACH', '{"type":"TEACH","title":"Time in a sentence","body":["Time words go near the **start**; the verb goes **last**."],"examples":[{"kk":"Сағат алтыда оянамын.","en":"I wake up at 6."},{"kk":"Сағат тоғызда кофе ішемін.","en":"At 9 I drink coffee."},{"kk":"Сағат сегізде жұмыс істеймін.","en":"At 8 I work."},{"kk":"Әдетте сағат жетіде оянамын.","en":"I usually wake up at 7."}]}'::jsonb, 'active', 'high'),
  ('u6-b4-e9', 'u6-b4', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Әдетте сағат жетіде оянамын.","options":["I never wake up at 7.","I usually wake up at 7.","I go to sleep at 7.","I wake up 7 times."],"correctAns":"I usually wake up at 7."}'::jsonb, 'active', 'high'),
  ('u6-b4-e10', 'u6-b4', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сағат тоғызда кофе ішемін.","options":["I drink 9 coffees.","At 9 I drink coffee.","At 10 I drink coffee.","At 9 I drink tea."],"correctAns":"At 9 I drink coffee."}'::jsonb, 'active', 'high'),
  ('u6-b4-e11', 'u6-b4', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"at 10 o''clock","tiles":["сағат","онда","он","бесте"],"correctAns":["сағат","онда"]}'::jsonb, 'active', 'high'),
  ('u6-b4-e12', 'u6-b4', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"сағат жетіде","options":["сағат жетіде","сағат екіде","сағат сегізде"],"correctAns":"сағат жетіде"}'::jsonb, 'active', 'high'),
  ('u6-b4-e13', 'u6-b4', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қызым әдетте сағат жетіде фильм қарайды.","options":["I usually watch a film at 7.","My daughter never watches films.","My daughter usually watches a film at 7.","My daughter wakes up at 7."],"correctAns":"My daughter usually watches a film at 7."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u6-b5-e1', 'u6-b5', 1, 'TEACH', '{"type":"TEACH","title":"The week — апта","table":{"headers":["Kazakh","English"],"rows":[["дүйсенбі","Monday"],["сейсенбі","Tuesday"],["сәрсенбі","Wednesday"],["бейсенбі","Thursday"],["жұма","Friday"],["сенбі","Saturday"],["жексенбі","Sunday"]]},"body":["*On Monday* uses the same ending: дүйсенбі**де**."]}'::jsonb, 'active', 'high'),
  ('u6-b5-e2', 'u6-b5', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"дүйсенбі","english":"Monday"},{"kazakh":"сейсенбі","english":"Tuesday"},{"kazakh":"сәрсенбі","english":"Wednesday"},{"kazakh":"бейсенбі","english":"Thursday"},{"kazakh":"жұма","english":"Friday"}]}'::jsonb, 'active', 'high'),
  ('u6-b5-e3', 'u6-b5', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"сенбі","english":"Saturday"},{"kazakh":"жексенбі","english":"Sunday"},{"kazakh":"апта","english":"week"},{"kazakh":"күн","english":"day"},{"kazakh":"және","english":"and"}]}'::jsonb, 'active', 'high'),
  ('u6-b5-e4', 'u6-b5', 4, 'LISTENING', '{"type":"LISTENING","audioKk":"сәрсенбі","options":["бейсенбі","сәрсенбі","сейсенбі"],"correctAns":"сәрсенбі"}'::jsonb, 'active', 'high'),
  ('u6-b5-e5', 'u6-b5', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["дүйсенбі",""],"options":["те","да","де"],"correctAns":"де","hintEn":"on Monday"}'::jsonb, 'active', 'high'),
  ('u6-b5-e6', 'u6-b5', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["жұма",""],"options":["да","де","та"],"correctAns":"да","hintEn":"on Friday"}'::jsonb, 'active', 'high'),
  ('u6-b5-e7', 'u6-b5', 7, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"бейсенбі","options":["Tuesday","Thursday","Friday","Wednesday"],"correctAns":"Thursday"}'::jsonb, 'active', 'high'),
  ('u6-b5-e8', 'u6-b5', 8, 'TEACH', '{"type":"TEACH","title":"Plans for the week","examples":[{"kk":"Жексенбіде демаламын.","en":"On Sunday I rest."},{"kk":"Сенбіде кофе ішемін.","en":"On Saturday I drink coffee."},{"kk":"Дүйсенбіде сағат онда жұмыс істеймін.","en":"On Monday at 10 I work."},{"kk":"Сенбі **және** жексенбіде демаламын.","en":"On Saturday and Sunday I rest."}]}'::jsonb, 'active', 'high'),
  ('u6-b5-e9', 'u6-b5', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Жексенбіде демаламын.","options":["On Sunday I work.","On Sunday I rest.","Every day I rest.","On Saturday I rest."],"correctAns":"On Sunday I rest."}'::jsonb, 'active', 'high'),
  ('u6-b5-e10', 'u6-b5', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"On Saturday and Sunday I rest.","tiles":["Сенбі","және","жексенбіде","демаламын","сенбіде","демалады"],"correctAns":["Сенбі","және","жексенбіде","демаламын"]}'::jsonb, 'active', 'high'),
  ('u6-b5-e11', 'u6-b5', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Дүйсенбіде сағат онда жұмыс істеймін.","options":["On Monday I work 10 hours.","On Monday at 10 I rest.","On Monday at 10 I work.","On Tuesday at 10 I work."],"correctAns":"On Monday at 10 I work."}'::jsonb, 'active', 'high'),
  ('u6-b5-e12', 'u6-b5', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Аптаң қалай?","options":["How''s your day?","What day is it?","Where''s your week?","How''s your week?"],"correctAns":"How''s your week?"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b1-e1', 'u7-b1', 1, 'TEACH', '{"type":"TEACH","title":"Verbs end in -у","body":["In the dictionary, Kazakh verbs end in **-у** (sometimes **-ю**). Remove it to get the **stem**: бар**у** → бар-, іш**у** → іш-."],"table":{"headers":["Verb","Meaning"],"rows":[["бару","to go"],["келу","to come"],["ішу","to drink"],["жеу","to eat"],["тұру","to live / stand / get up"],["ояну","to wake up"],["істеу / жасау","to do, to make"],["демалу","to rest"]]}}'::jsonb, 'active', 'high'),
  ('u7-b1-e2', 'u7-b1', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"бару","english":"to go"},{"kazakh":"ішу","english":"to drink"},{"kazakh":"жеу","english":"to eat"},{"kazakh":"тұру","english":"to live"},{"kazakh":"ояну","english":"to wake up"}]}'::jsonb, 'active', 'high'),
  ('u7-b1-e3', 'u7-b1', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"жазу","english":"to write"},{"kazakh":"көру","english":"to see"},{"kazakh":"демалу","english":"to rest"},{"kazakh":"ұйықтау","english":"to sleep"},{"kazakh":"келу","english":"to come"}]}'::jsonb, 'active', 'high'),
  ('u7-b1-e4', 'u7-b1', 4, 'LISTENING', '{"type":"LISTENING","audioKk":"ішу","options":["ішу","жеу","оқу"],"correctAns":"ішу"}'::jsonb, 'active', 'high'),
  ('u7-b1-e5', 'u7-b1', 5, 'TEACH', '{"type":"TEACH","title":"The verb goes last","body":["Kazakh word order is **Subject – Object – Verb**.","Descriptions come **before** what they describe: **жақсы** қызым, **қара** шай, **көп** ішеді."],"examples":[{"kk":"Қызым шай ішеді.","en":"My daughter drinks tea. (S – O – V)"},{"kk":"Мен ресторанда тамақ жеймін.","en":"I eat food in a restaurant."},{"kk":"Күнде үйде тамақ жейміз.","en":"Every day we eat at home."},{"kk":"Жақсы қызым қара шай көп ішеді.","en":"My good daughter drinks a lot of black tea."}]}'::jsonb, 'active', 'high'),
  ('u7-b1-e6', 'u7-b1', 6, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","questionEn":"Where does the verb go in a Kazakh sentence?","options":["At the start","At the end","Anywhere","Right after the subject"],"correctAns":"At the end"}'::jsonb, 'active', 'high'),
  ('u7-b1-e7', 'u7-b1', 7, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қызым шай ішеді.","options":["My daughter makes tea.","My daughter drinks coffee.","My daughter drinks tea.","I drink tea."],"correctAns":"My daughter drinks tea."}'::jsonb, 'active', 'high'),
  ('u7-b1-e8', 'u7-b1', 8, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My daughter drinks tea.","tiles":["Қызым","шай","ішеді","ішемін","кофе"],"correctAns":["Қызым","шай","ішеді"]}'::jsonb, 'active', 'high'),
  ('u7-b1-e9', 'u7-b1', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Күнде үйде тамақ жейміз.","options":["Every day we eat at home.","Every day we cook at home.","Every day I eat at home.","Today we eat at home."],"correctAns":"Every day we eat at home."}'::jsonb, 'active', 'high'),
  ('u7-b1-e10', 'u7-b1', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I eat food in a restaurant.","tiles":["Мен","ресторанда","тамақ","жеймін","ресторан","жейді"],"correctAns":["Мен","ресторанда","тамақ","жеймін"]}'::jsonb, 'active', 'high'),
  ('u7-b1-e11', 'u7-b1', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"жазу","options":["to see","to read","to rest","to write"],"correctAns":"to write"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b2-e1', 'u7-b2', 1, 'TEACH', '{"type":"TEACH","title":"Three steps","body":["1) Take the stem: бар**у** → бар.","2) Add a linking sound: **-а** after a consonant (strong word), **-е** after a consonant (soft word), **-й** after a vowel.","3) Add the ending: **-мын / -мін** for *I*."],"table":{"headers":["Verb","I …","Meaning"],"rows":[["бару","бар**амын**","I go"],["келу","кел**емін**","I come"],["ішу","іш**емін**","I drink"],["жасау","жаса**ймын**","I do"],["жеу","же**ймін**","I eat"],["ояну","оян**амын**","I wake up"]]},"tip":"This tense is for **habits** and the **near future**: барамын = *I go / I''ll go*. And **ей** sounds like *ий*: істеймін ≈ [істиймін]."}'::jsonb, 'active', 'high'),
  ('u7-b2-e2', 'u7-b2', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен ","."],"options":["барамін","барамын","баремын"],"correctAns":"барамын","hintEn":"I go."}'::jsonb, 'active', 'high'),
  ('u7-b2-e3', 'u7-b2', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Күнде кофе ","."],"options":["ішемын","ішамін","ішемін"],"correctAns":"ішемін","hintEn":"I drink coffee every day."}'::jsonb, 'active', 'high'),
  ('u7-b2-e4', 'u7-b2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат он екіде тамақ ","."],"options":["жеймын","жемін","жеймін"],"correctAns":"жеймін","hintEn":"At 12 I eat."}'::jsonb, 'active', 'high'),
  ('u7-b2-e5', 'u7-b2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат алтыда ","."],"options":["оянамін","оянамын","оянемын"],"correctAns":"оянамын","hintEn":"I wake up at 6."}'::jsonb, 'active', 'high'),
  ('u7-b2-e6', 'u7-b2', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сингапурда ","."],"options":["тұрамын","тұремын","тұрамін"],"correctAns":"тұрамын","hintEn":"I live in Singapore."}'::jsonb, 'active', 'high'),
  ('u7-b2-e7', 'u7-b2', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат жетіде салат ","."],"options":["жасамын","жасаймін","жасаймын"],"correctAns":"жасаймын","hintEn":"At 7 I make a salad."}'::jsonb, 'active', 'high'),
  ('u7-b2-e8', 'u7-b2', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сағат сегізде жұмыс ","."],"options":["істемін","істеймын","істеймін"],"correctAns":"істеймін","hintEn":"At 8 I work."}'::jsonb, 'active', 'high'),
  ('u7-b2-e9', 'u7-b2', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Тауды ","."],"options":["көрамін","көремін","көремын"],"correctAns":"көремін","hintEn":"I see the mountain."}'::jsonb, 'active', 'high'),
  ('u7-b2-e10', 'u7-b2', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Ерте оянамын.","options":["I wake up early.","Tomorrow I wake up.","I wake up late.","She wakes up early."],"correctAns":"I wake up early."}'::jsonb, 'active', 'high'),
  ('u7-b2-e11', 'u7-b2', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I drink coffee at home.","tiles":["Үйде","кофе","ішемін","ішеді","үй"],"correctAns":["Үйде","кофе","ішемін"]}'::jsonb, 'active', 'high'),
