insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b4-e1', 'u7-b4', 1, 'TEACH', '{"type":"TEACH","title":"When?","table":{"headers":["Kazakh","English"],"rows":[["әдетте","usually"],["күнде","every day"],["бүгін","today"],["ертең","tomorrow"],["ерте","early"],["көп","a lot"]]},"tip":"Time words usually go at the **start** of the sentence. Don''t mix up **ерте** (early) and **ертең** (tomorrow)!"}'::jsonb, 'active', 'high'),
  ('u7-b4-e2', 'u7-b4', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"әдетте","english":"usually"},{"kazakh":"күнде","english":"every day"},{"kazakh":"бүгін","english":"today"},{"kazakh":"ертең","english":"tomorrow"},{"kazakh":"ерте","english":"early"}]}'::jsonb, 'active', 'high'),
  ('u7-b4-e3', 'u7-b4', 3, 'TEACH', '{"type":"TEACH","title":"Food & drink","examples":[{"kk":"Әдетте қара кофе ішемін.","en":"I usually drink black coffee."},{"kk":"Досым сүт**пен** кофе ішеді.","en":"My friend drinks coffee with milk."},{"kk":"Қызым әдетте көк шай ішеді.","en":"My daughter usually drinks green tea."},{"kk":"Сенбіде пицца пісіремін.","en":"On Saturday I cook pizza."}],"tip":"**Көк** covers blue *and* green — **көк шай** = green tea. **Жасыл** is grass-green."}'::jsonb, 'active', 'high'),
  ('u7-b4-e4', 'u7-b4', 4, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"шай","english":"tea"},{"kazakh":"су","english":"water"},{"kazakh":"сүт","english":"milk"},{"kazakh":"тамақ","english":"food"},{"kazakh":"қара","english":"black"}]}'::jsonb, 'active', 'high'),
  ('u7-b4-e5', 'u7-b4', 5, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Досым күнде қара шай ішеді.","options":["My friend drinks black coffee today.","My friend drinks green tea every day.","I drink black tea every day.","My friend drinks black tea every day."],"correctAns":"My friend drinks black tea every day."}'::jsonb, 'active', 'high'),
